import pytest
from ta_attenuator.attenuators_impls.jfw import JfwAttenuator
from mock import call, Mock, patch
from ta_attenuator.attenuator import ReadingAttenuationValueOfNonexistentRFPath
from ta_attenuator.attenuator import AttenuationValueIsOtherThanExpected
from test.common_test_scenarios_for_attenuator_implementations import \
    reserving_ports_on_attenuator_success
from test.common_test_scenarios_for_attenuator_implementations import \
    reserving_ports_on_attenuator_duplicate_id
from test.common_test_scenarios_for_attenuator_implementations import \
    releasing_ports_on_attenuator_success
from test.common_test_scenarios_for_attenuator_implementations import \
    releasing_not_reserved_port_on_attenuator_causes_exception
from test.common_test_scenarios_for_attenuator_implementations import \
    setting_attenuation_value_on_not_reserved_port


def test_reserving_ports_on_jfw_success(jfw_object):
    reserving_ports_on_attenuator_success(jfw_object)


def test_reserving_ports_on_jfw_duplicate_id(jfw_object):
    reserving_ports_on_attenuator_duplicate_id(jfw_object)


def test_releasing_ports_on_jfw_success(jfw_object):
    releasing_ports_on_attenuator_success(jfw_object)


def test_releasing_not_reserved_port_on_jfw_causes_exception(jfw_object):
    releasing_not_reserved_port_on_attenuator_causes_exception(jfw_object)


def test_setting_attenuation_on_not_reserved_jfw_port_causes_exception(jfw_object):
    setting_attenuation_value_on_not_reserved_port(jfw_object)


@patch.multiple(JfwAttenuator, _write=Mock(), _make_sure_port_has_correct_value=Mock())
def test_method_set_single_path_attenuation_constructs_correct_command_for_jfw(jfw_object):
    rf_path_to_reserve = 1
    attenuation_value = 40
    expected_command = "SA{} {}".format(rf_path_to_reserve, attenuation_value)
    expected_call = [call(expected_command)]
    jfw_object.reserve_port(rf_path_to_reserve)
    jfw_object._set_single_rf_path_decibel_attenuation(rf_path_to_reserve, attenuation_value)
    jfw_object._write.assert_has_calls(expected_call)


def test_reading_attenuation_value_of_rf_path_for_jfw_success(jfw_object):
    att_output = "Atten #3 = 66dB\n"
    jfw_object.telnet.read_command = Mock(return_value=att_output)
    retrieved_value = jfw_object._read_attenuation_value(str(3))
    assert retrieved_value == '66'


def test_reading_attenuation_value_of_rf_path_for_jfw_on_blocks(jfw_on_blocks):
    att_output = "Block #1 = 20dB, PATS: 1,2\n"
    jfw_on_blocks.telnet.read_command = Mock(return_value=att_output)
    retrieved_value = jfw_on_blocks._read_attenuation_value(str(3))
    assert jfw_on_blocks.mode == 'blocks'
    assert retrieved_value == '20'


@pytest.mark.parametrize("mode,att_output,expected_command", [
    ('ports', 'Atten #1 = 50dB\n', 'SA1 50'),
    ('blocks', 'Block #1 = 50dB, PATS: 1,2\n', 'SB1 50')
])
def test_setting_attenuation_uses_correct_command(jfw_on_blocks, mode, att_output, expected_command):
    jfw_on_blocks.mode = mode
    reserving_ports_on_attenuator_success(jfw_on_blocks)
    jfw_on_blocks.telnet = Mock()
    jfw_on_blocks.telnet.read_command = Mock(return_value=att_output)
    assert jfw_on_blocks._prepare_set_command('50', '1') == expected_command
    jfw_on_blocks._set_single_rf_path_decibel_attenuation(1, 50)


def test_reading_attenuation_value_of_nonexistent_rf_path_on_jfw_causes_exception(jfw_object):
    att_output = "Atten 13 does not exist"
    jfw_object.telnet.read_command = Mock(return_value=att_output)
    with pytest.raises(ReadingAttenuationValueOfNonexistentRFPath):
        jfw_object._read_attenuation_value(str(13))


def test_attenuation_value_other_than_desired_on_jfw_causes_exception(jfw_object):
    desired_value = 40
    actual_value = 30
    jfw_object._read_attenuation_value = Mock(return_value=actual_value)
    with pytest.raises(AttenuationValueIsOtherThanExpected):
        jfw_object._make_sure_port_has_correct_value(1, desired_value, True)


@pytest.fixture()
def jfw_object():
    min_attenuation = 0
    max_attenuation = 60
    port = 3001
    ip = '127.0.0.1'
    attenuator_object = JfwAttenuator(min_attenuation, max_attenuation, ip, port)
    return attenuator_object


@pytest.fixture()
def jfw_on_blocks():
    min_attenuation = 0
    max_attenuation = 60
    port = 3001
    ip = '127.0.0.1'
    mode = 'blocks'
    attenuator_object = JfwAttenuator(min_attenuation, max_attenuation, ip, port, mode)
    return attenuator_object
